const patients = $input.all();
const searchTerm = $('Slack Commands Webhook').item.json.body.text || '';

// Date formatter: convert any date to DD.MM.YYYY
const formatDate = (dateStr) => {
  if (!dateStr || dateStr === '-') return '-';
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    return `${day}.${month}.${year}`;
  } catch (e) {
    return dateStr;
  }
};

if (patients.length === 0) {
  return [{ json: { response_type: 'ephemeral', text: `Пацієнта "${searchTerm}" не знайдено` } }];
}

// Build blocks with patient info and buttons
const blocks = [];

for (const p of patients) {
  const f = p.json.fields || p.json;
  const recordId = p.json.id || '';
  const name = f['ПІБ'] || 'Невідомо';
  const ward = f['Палата'] || '-';
  const diagnosis = f['Діагноз'] || '-';
  const doctor = f['Хірург'] || '-';
  const admDate = formatDate(f['Дата госпіталізації']);
  const vlkDate = formatDate(f['Дата ВЛК']);
  const vlkDecision = f['Рішення ВЛК'] || '';
  const vlkDays = f['Дні продовження'] || '';

  // Build VLK status line
  let vlkLine = '';
  if (f['Дата ВЛК'] || vlkDecision) {
    vlkLine = `\nВЛК: ${vlkDate}`;
    if (vlkDecision) vlkLine += ` (${vlkDecision}`;
    if (vlkDays) vlkLine += `, +${vlkDays} днів`;
    if (vlkDecision) vlkLine += ')';
  }

  // Patient info block
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*${name}*\nПалата: ${ward}\nДіагноз: ${diagnosis}\nХірург: ${doctor}\nДата госпіталізації: ${admDate}${vlkLine}`
    }
  });

  // Buttons block
  blocks.push({
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: '📋 Деталі', emoji: true },
        action_id: `details_${recordId}`,
        value: name
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: '🏥 ВЛК', emoji: true },
        action_id: `vlk_schedule_${recordId}`,
        value: name,
        style: 'primary'
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: '📄 Довідка', emoji: true },
        action_id: `dovidka_${recordId}`,
        value: name
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: '🚪 Виписка', emoji: true },
        action_id: `discharge_${recordId}`,
        value: name,
        style: 'danger'
      }
    ]
  });

  // Divider between patients
  blocks.push({ type: 'divider' });
}

return [{ json: { response_type: 'ephemeral', blocks } }];

const ops = $input.all();
const today = new Date();
const dayOfWeek = today.getDay();

let dateLabel = 'сьогодні';
if (dayOfWeek === 5) dateLabel = 'понеділок';

if (ops.length === 0) {
  return [{ json: { response_type: 'in_channel', text: `Операцій на ${dateLabel} не заплановано` } }];
}

let text = `*Операції на ${dateLabel} (${ops.length}):*\n\n`;

for (let i = 0; i < ops.length; i++) {
  const f = ops[i].json.fields || ops[i].json;
  text += `${i+1}. *${f['Назва операції'] || f['Пацієнт'] || 'Операція'}*\n`;
  text += `   Пацієнт: ${f['Пацієнт'] || '-'}\n`;
  text += `   Хірург: ${f['Хірург'] || '-'}\n`;
  text += `   Час: ${f['Час'] || '-'}\n\n`;
}

return [{ json: { response_type: 'in_channel', text } }];

const patients = $input.all();

const wards = {};
for (const p of patients) {
  const f = p.json.fields || p.json;
  const ward = f['Палата'] || 'Невідомо';
  wards[ward] = (wards[ward] || 0) + 1;
}

let text = `*Заповненість палат (${patients.length} пацієнтів):*\n\n`;

const sortedWards = Object.keys(wards).sort();
for (const ward of sortedWards) {
  text += `Палата ${ward}: ${wards[ward]} пацієнт(ів)\n`;
}

return [{ json: { response_type: 'in_channel', text } }];

const patients = $input.all();

if (patients.length === 0) {
  return [{ json: { response_type: 'in_channel', text: 'Немає пацієнтів, що потребують ВЛК' } }];
}

let critical = [];
let warning = [];

for (const p of patients) {
  const f = p.json.fields || p.json;
  const days = f['Дні з травми'] || 0;
  const vlkStatus = f['ВЛК статус'] || '';

  if (vlkStatus.includes('Пройдено')) continue;

  const name = f['ПІБ'] || 'Невідомо';

  if (days >= 120) {
    critical.push({ name, days });
  } else if (days >= 100) {
    warning.push({ name, days });
  }
}

let text = '*ВЛК Статус:*\n\n';

if (critical.length > 0) {
  text += `*ПОТРІБНА ВЛК (${critical.length}):*\n`;
  for (const p of critical) {
    text += `  ${p.name} - ${p.days} днів\n`;
  }
  text += '\n';
}

if (warning.length > 0) {
  text += `*До ВЛК (${warning.length}):*\n`;
  for (const p of warning) {
    text += `  ${p.name} - ${p.days} днів\n`;
  }
}

if (critical.length === 0 && warning.length === 0) {
  text = 'Всі пацієнти в нормі по ВЛК';
}

return [{ json: { response_type: 'in_channel', text } }];

const patients = $input.all();

const total = patients.length;
let vlkCritical = 0;
let vlkWarning = 0;

for (const p of patients) {
  const f = p.json.fields || p.json;
  const days = f['Дні з травми'] || 0;
  const vlkStatus = f['ВЛК статус'] || '';

  if (vlkStatus.includes('Пройдено')) continue;

  if (days >= 120) vlkCritical++;
  else if (days >= 100) vlkWarning++;
}

const text = `*Швидка статистика:*\n\n` +
  `Госпіталізовано: ${total}\n` +
  `ВЛК критичні: ${vlkCritical}\n` +
  `ВЛК попередження: ${vlkWarning}\n`;

return [{ json: { response_type: 'in_channel', text } }];

// Check if patient name was provided
const text = $('Slack Commands Webhook').item.json.body.text || '';
const patientName = text.trim();

// Base surgery form URL
const baseUrl = 'https://airtable.com/appv5BwoWyRhT6Lcr/pagHhn65IOwuk3SgF/form';

if (patientName) {
  // Check if we found a patient in Airtable
  const searchResults = $('Search Surgery Patient').all();

  if (searchResults.length > 0 && searchResults[0].json.id) {
    // Found patient - get data with fallback for different Airtable node versions
    const patient = searchResults[0].json;
    const f = patient.fields || patient;  // Handle both structures!

    const patientRecordId = patient.id;
    const foundName = f['ПІБ'] || patientName;
    const historyNum = f['№ історії'] || '';
    const surgeon = f['Хірург'] || '';

    // Build prefill params
    const prefills = {
      'Пацієнт': patientRecordId,
      '№ і/х': historyNum,
      'Хірург': surgeon
    };

    const params = Object.entries(prefills)
      .filter(([k, v]) => v !== '' && v !== null && v !== undefined)
      .map(([k, v]) => 'prefill_' + encodeURIComponent(k) + '=' + encodeURIComponent(String(v)))
      .join('&');

    const prefillUrl = params ? baseUrl + '?' + params : baseUrl;

    return [{
      json: {
        response_type: 'ephemeral',
        text: `*Запис на операцію для: ${foundName}*\n№ і/х: ${historyNum || '-'}\nХірург: ${surgeon || '-'}\n\nЗаповніть форму:\n${prefillUrl}`
      }
    }];
  } else {
    // Patient not found - show form without prefill
    return [{
      json: {
        response_type: 'ephemeral',
        text: `*Пацієнта "${patientName}" не знайдено*\n\nЗаповніть форму вручну:\n${baseUrl}\n\n_Перевірте правильність прізвища_`
      }
    }];
  }
} else {
  // No patient name - show generic link
  return [{
    json: {
      response_type: 'ephemeral',
      text: '*Запис на операцію:*\n\nЗаповніть форму для запису пацієнта на операцію:\n' + baseUrl + '\n\n_Підказка: напишіть `/surgery Прізвище` щоб заповнити ПІБ автоматично_'
    }
  }];
}
